using System;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;
namespace FssLauncher{public sealed class VbucksDialog:Form{readonly Label message=new Label();readonly LauncherForm launcher;bool pending;string pendingReceipt;int pendingQuantity;public VbucksDialog(LauncherForm owner){launcher=owner;Text="Simulator V-Bucks";Icon=Branding.AppIcon();BackColor=Color.FromArgb(32,32,32);ForeColor=Color.White;ClientSize=new Size(420,330);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=MinimizeBox=false;var title=new Label{Text="SIMULATOR V-BUCKS",Font=new Font("Segoe UI",16,FontStyle.Bold)};title.SetBounds(25,22,370,35);Controls.Add(title);var description=new Label{Text="Free packs for your local account. No real-money payment."};description.SetBounds(25,65,370,45);Controls.Add(description);int row=0;foreach(int amount in new[]{1000,2800,7500,13500}){int quantity=amount;var button=new FlatAction{Text=amount.ToString("N0")+" V-Bucks"};button.SetBounds(25+(row%2)*190,118+(row/2)*58,180,44);Controls.Add(button);button.Click+=async delegate{if(pending)return;if(pendingReceipt!=null&&pendingQuantity!=quantity){message.Text="Retry the previous pack first to confirm its balance.";return;}pending=true;message.Text="Adding pack...";if(pendingReceipt==null){pendingReceipt=Guid.NewGuid().ToString("N");pendingQuantity=quantity;}string receipt=pendingReceipt;try{message.Text="Balance: "+(await launcher.PurchaseVbucks(quantity,receipt)).ToString("N0")+" V-Bucks. Reopen the in-game lobby to refresh.";pendingReceipt=null;}catch(Exception error){message.Text=error.Message;}finally{pending=false;}};row++;}message.SetBounds(25,245,370,65);Controls.Add(message);}}}
